<script setup lang="ts">import { onMounted, ref } from "vue"; import { createSupplier, listSuppliers, type Supplier } from "../api"; const suppliers = ref<Supplier[]>([]); const form = ref({ name: "", email: "", phone: "", notes: "" }); async function load() { suppliers.value = await listSuppliers(); } async function save() { await createSupplier(form.value); form.value = { name: "", email: "", phone: "", notes: "" }; await load(); } onMounted(load);</script><template><section><header><div><p class="eyebrow">Almacen</p><h1>Proveedores</h1></div></header><div class="operations-grid"><section class="operation-panel"><ul class="operation-list"><li v-for="supplier in suppliers" :key="supplier.id"><div><strong>{{ supplier.name }}</strong><span>{{ supplier.email || supplier.phone || "Sin contacto" }}</span></div></li></ul><p v-if="!suppliers.length" class="empty">No hay proveedores.</p></section><form class="operation-panel operation-form" @submit.prevent="save"><h2>Nuevo proveedor</h2><label>Nombre<input v-model="form.name" required /></label><label>Email<input v-model="form.email" type="email" /></label><label>Telefono<input v-model="form.phone" /></label><button>Guardar proveedor</button></form></div></section></template>